package com.juan.habitos.ui.adult

import androidx.compose.foundation.*
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.*
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.juan.habitos.domain.model.DeviceMode
import com.juan.habitos.ui.state.*
import com.juan.habitos.ui.theme.*

@Composable fun DeviceModeSelectionScreen(onMode: (DeviceMode) -> Unit) { SetupFrame { Text("¿Cómo se va a utilizar este dispositivo?", color = Color.White, fontSize = 28.sp, fontWeight = FontWeight.Bold); Text("Elegí una opción para preparar Moderá.", color = Color(0xFFCBD5E1)); Spacer(Modifier.height(24.dp)); ModeCard("🧒", "Dispositivo del niño", "Configurar perfil, permisos y vista infantil") { onMode(DeviceMode.CHILD) }; ModeCard("👤", "Dispositivo del adulto", "Consultar perfiles infantiles vinculados") { onMode(DeviceMode.ADULT) } } }

@Composable fun AdultEmailScreen(state: AdultAuthUiState, onEmail: (String) -> Unit, onContinue: () -> Unit) { SetupFrame { SetupHeader("Accedé a Moderá", "Usá tu correo electrónico para acceder a los perfiles que tengas vinculados."); Spacer(Modifier.height(24.dp)); OutlinedTextField(state.email, onEmail, Modifier.fillMaxWidth(), label = { Text("Correo electrónico") }, placeholder = { Text("nombre@correo.com") }, singleLine = true, isError = state.emailError, supportingText = if (state.emailError) ({ Text("Ingresá un correo electrónico válido.") }) else null, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email), colors = setupTextFieldColors()); Spacer(Modifier.height(18.dp)); SetupButton("Continuar", !state.loading, onContinue) } }

@Composable fun AdultVerificationScreen(state: AdultAuthUiState, onCode: (String) -> Unit, onVerify: () -> Unit, onBack: () -> Unit) { SetupFrame { TextButton(onBack, contentPadding = PaddingValues(0.dp)) { Text("← Volver", color = Color(0xFFCBD5E1)) }; SetupHeader("Revisá tu correo", "Enviamos un código de verificación a\n${state.email}"); Spacer(Modifier.height(24.dp)); CodeField(state.code, onCode, "Código de 6 dígitos", state.codeError); if (state.codeError) Text("El código ingresado no es válido.", color = MaterialTheme.colorScheme.error, fontSize = 13.sp); Spacer(Modifier.height(18.dp)); SetupButton("Verificar", state.code.length == 6 && !state.loading, onVerify) } }

@Composable fun AdultLinkProfileScreen(state: LinkDeviceUiState, onCode: (String) -> Unit, onFind: () -> Unit, onConfirm: () -> Unit) { SetupFrame(scroll = true) { SetupHeader("Vinculá el dispositivo de un niño", "Para consultar su información desde este celular, ingresá el código generado desde el dispositivo del niño."); Spacer(Modifier.height(22.dp)); CodeField(state.code, onCode, "Código de vinculación", state.error); if (state.error) Text("No encontramos un perfil con ese código.", color = MaterialTheme.colorScheme.error, fontSize = 13.sp); Spacer(Modifier.height(14.dp)); if (state.foundProfile == null) SetupButton("Vincular", state.code.length == 6 && !state.loading, onFind); state.foundProfile?.let { profile -> Card(colors = CardDefaults.cardColors(containerColor = AppColors.Card), border = BorderStroke(1.dp, AppColors.PurpleSoft), shape = RoundedCornerShape(18.dp)) { Column(Modifier.fillMaxWidth().padding(20.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Perfil encontrado", color = AppColors.PurpleSoft, fontWeight = FontWeight.Bold); Text(profile.avatar, fontSize = 50.sp); Text(profile.name, color = Color.White, fontSize = 21.sp, fontWeight = FontWeight.Bold); Text("${profile.age} años", color = Color(0xFFCBD5E1)); Spacer(Modifier.height(6.dp)); SetupButton("Vincular perfil", true, onConfirm) } } }; Spacer(Modifier.height(20.dp)); Surface(color = AppColors.Card, shape = RoundedCornerShape(14.dp)) { Column(Modifier.padding(16.dp)) { Text("¿Dónde encuentro el código?", color = Color.White, fontWeight = FontWeight.Bold); Text("Desde el dispositivo del niño, ingresá al panel adulto y buscá la opción de vinculación.", color = Color(0xFFCBD5E1), fontSize = 13.sp, lineHeight = 19.sp) } } } }

@Composable private fun SetupFrame(scroll: Boolean = false, content: @Composable ColumnScope.() -> Unit) { val modifier = Modifier.fillMaxSize().background(AppColors.Surface).statusBarsPadding().navigationBarsPadding().padding(24.dp).let { if (scroll) it.verticalScroll(rememberScrollState()) else it }; Column(modifier, verticalArrangement = if (scroll) Arrangement.Top else Arrangement.Center, content = content) }
@Composable private fun SetupHeader(title: String, subtitle: String) { Text(title, color = Color.White, fontSize = 28.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(10.dp)); Text(subtitle, color = Color(0xFFCBD5E1), lineHeight = 22.sp) }
@Composable private fun ModeCard(icon: String, title: String, subtitle: String, onClick: () -> Unit) { Surface(onClick = onClick, Modifier.fillMaxWidth().padding(bottom = 14.dp), color = AppColors.Card, shape = RoundedCornerShape(18.dp), border = BorderStroke(1.dp, AppColors.Divider)) { Row(Modifier.padding(18.dp), verticalAlignment = Alignment.CenterVertically) { Text(icon, fontSize = 34.sp); Spacer(Modifier.width(14.dp)); Column(Modifier.weight(1f)) { Text(title, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 17.sp); Text(subtitle, color = Color(0xFF94A3B8), fontSize = 13.sp) }; Text("›", color = AppColors.PurpleSoft, fontSize = 28.sp) } } }
@Composable private fun CodeField(value: String, onValue: (String) -> Unit, label: String, error: Boolean) { OutlinedTextField(value, onValue, Modifier.fillMaxWidth(), label = { Text(label) }, placeholder = { Text("_  _  _  _  _  _") }, singleLine = true, isError = error, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword), textStyle = LocalTextStyle.current.copy(fontSize = 23.sp, letterSpacing = 8.sp, fontWeight = FontWeight.Bold), colors = setupTextFieldColors()) }
@Composable private fun SetupButton(text: String, enabled: Boolean, onClick: () -> Unit) { Button(onClick, Modifier.fillMaxWidth().height(54.dp), enabled = enabled, colors = ButtonDefaults.buttonColors(containerColor = AppColors.Purple), shape = RoundedCornerShape(14.dp)) { Text(text, fontWeight = FontWeight.Bold) } }
@Composable private fun setupTextFieldColors() = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White, focusedBorderColor = AppColors.PurpleSoft, unfocusedBorderColor = AppColors.Divider, focusedLabelColor = AppColors.PurpleSoft, unfocusedLabelColor = Color(0xFF94A3B8), cursorColor = AppColors.PurpleSoft, errorSupportingTextColor = MaterialTheme.colorScheme.error)
